// Cyrus eval journal statistics: pass@1, repair share of spend and the top repair triggers of any eval journal, so the next
// run proves (or disproves) a reliability change.
//
//   npx tsx scripts/cyrus/eval-journal-stats.ts /root/cyrus-eval/first1/journal.jsonl
//   npx tsx scripts/cyrus/eval-journal-stats.ts /root/cyrus-eval/first2            (a run directory: journal.jsonl inside)
//   npx tsx scripts/cyrus/eval-journal-stats.ts first1/journal.jsonl --builds /path/with/ev-first1-*/build.json
//   npx tsx scripts/cyrus/eval-journal-stats.ts first2 --compare first1            (delta against a baseline run)
//   npx tsx scripts/cyrus/eval-journal-stats.ts first1 --json
//
// Triggers: results written by the runner since 2026-10-13 carry `triggers`; for older journals pass --builds, a directory
// holding <build id>/build.json copied from the service (read-only). Pure file reads, no network.
import fs from "node:fs";
import path from "node:path";
import { compareText, journalStats, repairTriggers, statsText, type StatRow } from "../../lib/cyrus/eval/stats";

const argv = process.argv.slice(2);
const opt = (n: string) => { const i = argv.indexOf(`--${n}`); return i >= 0 ? argv[i + 1] : undefined; };
const flag = (n: string) => argv.includes(`--${n}`);
const positional = argv.filter((a, i) => !a.startsWith("--") && !(i > 0 && ["--builds", "--compare"].includes(argv[i - 1])));

function journalPath(p: string): string {
  return fs.existsSync(p) && fs.statSync(p).isDirectory() ? path.join(p, "journal.jsonl") : p;
}

export function rowsOf(file: string, buildsDir?: string): StatRow[] {
  const last = new Map<string, StatRow>();
  for (const line of fs.readFileSync(file, "utf8").split("\n")) {
    if (!line.trim()) continue;
    let j: { t?: string; job?: string; result?: Record<string, unknown> };
    try { j = JSON.parse(line); } catch { continue; }
    if (j.t !== "done" || !j.result || !j.job) continue;
    const r = j.result as { lane?: string; status?: string; pass?: boolean; firstAttempt?: boolean; full?: boolean; repairs?: number; costUsd?: number; buildId?: string; triggers?: string[]; infra?: boolean };
    if (r.infra) continue;
    let triggers = r.triggers;
    if (!triggers && buildsDir && r.buildId) {
      try { triggers = repairTriggers(JSON.parse(fs.readFileSync(path.join(buildsDir, r.buildId, "build.json"), "utf8"))); } catch { /* record not copied */ }
    }
    last.set(j.job, { job: j.job, lane: r.lane ?? "other", status: r.status, pass: !!r.pass, firstAttempt: !!r.firstAttempt, full: !!r.full, repairs: r.repairs ?? 0, costUsd: r.costUsd ?? 0, ...(triggers ? { triggers } : {}) });
  }
  return [...last.values()];
}

function main() {
  if (!positional[0]) { console.error("usage: eval-journal-stats.ts <journal.jsonl | run dir> [--builds DIR] [--compare <journal | run dir>] [--json]"); process.exit(2); }
  const builds = opt("builds");
  const s = journalStats(rowsOf(journalPath(positional[0]), builds));
  if (flag("json")) console.log(JSON.stringify(s, null, 2));
  else console.log(statsText(s, positional[0]));
  const cmp = opt("compare");
  if (cmp) {
    const b = journalStats(rowsOf(journalPath(cmp), builds));
    console.log(`\nversus ${cmp}\n${compareText(b, s)}`);
  }
}
main();
