// Cyrus eval runner (one command). Run from a repo checkout (NOT /opt/nxeon); it only makes HTTP calls to the build
// service and, with --testflight, ssh flights on node-2 (one at a time, node-2 serialises them).
//
//   npx tsx scripts/cyrus/eval-run.ts --dry-run --preset first-run                      plan + cost estimate, submits nothing
//   npx tsx scripts/cyrus/eval-run.ts --tag first1 --preset first-run --budget 40 --testflight
//   npx tsx scripts/cyrus/eval-run.ts --dry-run --preset coverage-first --versions 1.21.11,1.21.1   (bundle mc-coverage: 42 builds)
//   npx tsx scripts/cyrus/eval-run.ts --tag tex4 --lanes texture:10 --versions 1.21.4,1.21.11 --budget 10
//   npx tsx scripts/cyrus/eval-run.ts --tag k1 --keys s01-heal,x01-backdoor --budget 2
//   npx tsx scripts/cyrus/eval-run.ts --tag first1 --report-only                       rebuild baseline/report from the journal
//
// Options: --versions (default 1.21.11; 26.x is skipped until the registry says buildable), --lanes lane:n,...
// (texture, sound, designer, datapack, plain, other; n or "all"), --keys, --categories, --core, --max-builds N,
// --model katara|saka|yakko (default saka), --budget USD (REQUIRED for a real run), --in-flight N (default 2),
// --out DIR (default /root/cyrus-eval), --url/--key (default MODBUILDER_URL/KEY or the configured env file).
// Resumable: rerun the same command after an interruption; finished builds are kept, submitted ones re-attached.
// Writes <out>/<tag>/{journal.jsonl,baseline.json,report.md,jars/}. Copy baseline.json to
// services/modbuilder/eval/baseline.json only after the owner accepts the run.
import fs from "node:fs";
import path from "node:path";
import { loadEvalSet, loadMatrix, LANES } from "../../lib/cyrus/eval/set";
import { COVERAGE_FIRST_RUN, FIRST_RUN, parseLanes, planRun, readJournal, runPlan, type JobResult } from "../../lib/cyrus/eval/run";
import { laneAccuracy, laneAccuracyMarkdown } from "../../lib/cyrus/eval/lanes";
import { buildBaseline, dryRunText, reportMarkdown } from "../../lib/cyrus/eval/report";
import { evalFlight } from "../../lib/cyrus/eval/flight";
import { isCyrusModel } from "../../lib/cyrus/models";

const argv = process.argv.slice(2);
const flag = (n: string) => argv.includes(`--${n}`);
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d; };
const list = (s: string) => s.split(",").map((x) => x.trim()).filter(Boolean);

async function main() {
  const dry = flag("dry-run");
  const tag = opt("tag", dry ? "dry-run" : "");
  if (!tag) throw new Error("--tag is required (a name for this run, e.g. first1)");
  const model = opt("model", "saka");
  if (!isCyrusModel(model)) throw new Error("--model must be katara, saka or yakko");
  const preset = opt("preset");
  if (preset && preset !== "first-run" && preset !== "coverage-first") throw new Error("--preset: first-run or coverage-first");
  const lanesArg = opt("lanes");
  const sel = {
    versions: list(opt("versions", "1.21.11")),
    lanes: lanesArg ? parseLanes(lanesArg) : preset === "first-run" ? FIRST_RUN : undefined,
    keys: opt("keys") ? list(opt("keys")) : preset === "coverage-first" ? [...COVERAGE_FIRST_RUN] : undefined,
    categories: opt("categories") ? list(opt("categories")) : undefined,
    core: flag("core"),
    maxBuilds: opt("max-builds") ? parseInt(opt("max-builds"), 10) : undefined,
  };
  if (!sel.lanes && !sel.keys && !sel.categories) throw new Error(`choose prompts: --preset first-run, --lanes (${LANES.join(", ")}), --keys or --categories`);
  const plan = planRun(loadEvalSet(), loadMatrix(), sel, { tag, model });
  const budget = parseFloat(opt("budget", "0"));
  const out = path.resolve(opt("out", "/root/cyrus-eval"));
  // Lane selection (bundle mc-coverage): scored offline for the planned prompts that carry expectLanes (no model call).
  const lanePrompts = [...new Map(plan.jobs.map((j) => [j.key, j.prompt])).values()].filter((p) => p.expectLanes);
  const lanes = lanePrompts.length ? laneAccuracy(lanePrompts) : null;
  if (dry) { console.log(dryRunText(plan, budget || plan.estimate.high)); if (lanes) console.log(`lane selection (${lanes.selector}): exact ${lanes.exactPct}% precision ${lanes.precisionPct}% recall ${lanes.recallPct}% over ${lanes.prompts} prompts`); return; }
  const dir = path.join(out, tag);
  const write = (rs: JobResult[], s: { spentUsd: number; stoppedForBudget: boolean; pending: string[] }, service: Record<string, unknown> | null) => {
    const b = buildBaseline(plan, rs, { real: true, budgetUsd: budget, ...s, service });
    fs.writeFileSync(path.join(dir, "baseline.json"), JSON.stringify(b, null, 1) + "\n");
    fs.writeFileSync(path.join(dir, "report.md"), reportMarkdown(b, rs) + (lanes ? "\n" + laneAccuracyMarkdown(lanes) : ""));
    console.log(`wrote ${dir}/baseline.json and report.md: final pass ${b.totals.finalPassPct ?? "-"}%, full ${b.totals.fullPassPct ?? "-"}%, spent $${b.spentUsd}`);
  };
  if (flag("report-only")) {
    const rs = readJournal(path.join(dir, "journal.jsonl")).flatMap((l) => (l.t === "done" ? [l.result] : []));
    write(rs, { spentUsd: Math.round(rs.reduce((a, r) => a + r.costUsd, 0) * 100) / 100, stoppedForBudget: false, pending: plan.jobs.filter((j) => !rs.some((r) => r.job === j.job)).map((j) => j.job) }, null);
    return;
  }
  if (!(budget > 0)) throw new Error("--budget USD is required for a real run (the run stops submitting before the cap)");
  const { modBuilderConfig } = await import("../../lib/modbuilder/client");
  const cfg = opt("url") && opt("key") ? { url: opt("url").replace(/\/+$/, ""), key: opt("key") } : modBuilderConfig();
  if (!cfg) throw new Error("no build service configured (MODBUILDER_URL / MODBUILDER_API_KEY or the env file)");
  const call = async (method: string, p: string, body?: unknown) => {
    const r = await fetch(cfg.url + p, { method, headers: { Authorization: `Bearer ${cfg.key}`, "Content-Type": "application/json" }, body: body === undefined ? undefined : JSON.stringify(body) });
    if (r.status === 404) return null;
    if (!r.ok) throw new Error(`${method} ${p}: HTTP ${r.status} ${(await r.text()).slice(0, 200)}`);
    return r;
  };
  const health = (await (await call("GET", "/health"))?.json()) as Record<string, unknown> | null;
  console.log(`build service ${cfg.url}: image ${health?.image ?? "?"}; ${plan.jobs.length} builds planned, estimate $${plan.estimate.low}-$${plan.estimate.high}, cap $${budget}`);
  const tf = flag("testflight");
  const run = tf ? (await import("../../lib/cyrus/testflight/client")).runTestFlight : null;
  const summary = await runPlan(plan, {
    submit: async (b) => (await (await call("POST", "/builds", b))!.json()) as { status?: string },
    get: async (id) => { const r = await call("GET", `/builds/${id}`); return r ? await r.json() : null; },
    flight: run ? (job, rec) => evalFlight(job.version, rec, { jarDir: path.join(dir, "jars"), run: (s) => run(s), artifact: async (id) => Buffer.from(await (await call("GET", `/builds/${id}/artifact`))!.arrayBuffer()) }) : undefined,
    log: (l) => console.log(l),
  }, { out, budgetUsd: budget, maxInFlight: parseInt(opt("in-flight", "2"), 10) });
  write(summary.done, summary, health ? { image: health.image, version: health.version, features: health.features } : null);
  if (summary.pending.length) { console.log(`${summary.pending.length} job(s) not finished${summary.stoppedForBudget ? " (budget cap)" : ""}: rerun the same command to resume`); process.exitCode = 3; }
}

main().catch((e) => { console.error(`eval-run: ${(e as Error).message}`); process.exit(2); });
