// Cyrus eval journal statistics (pure): pass@1, how much of the spend went to builds that needed a model repair, and which
// triggers caused the repairs. Used by scripts/cyrus/eval-journal-stats.ts so a new run proves (or disproves) a reliability change.
// Triggers come from the build service record (events + precheck rules), stored on every journal result as `triggers` since
// 2026-10-13; older journals can be joined with the service's build records (scripts/cyrus/eval-journal-stats.ts --builds DIR).

export type StatRow = {
  job: string; lane: string; status?: string; pass: boolean; firstAttempt: boolean; full?: boolean; repairs: number; costUsd: number; triggers?: string[];
};

/** The service record fields the trigger extraction reads. */
export type TriggerRecord = {
  events?: { message?: string }[] | null;
  precheck?: { rule?: string; attempt?: number }[] | null;
  repairPlan?: { kind?: string }[] | null;
};

/** Label for a design lane that was downgraded to a plain build (no model repair ran). */
export const DESIGN_DOWNGRADE = "design lane downgraded to plain build (no repair)";
const REPAIR_SAY = /^(.*?)\.? Fixing it automatically \(fix (\d+) of \d+\)/;

/** One label per model repair, e.g. "perf-spawn-in-loop", "No design found", "Sound check problems", "compile errors". */
export function repairTriggers(rec: TriggerRecord | null | undefined): string[] {
  if (!rec) return [];
  const out: string[] = [];
  for (const e of rec.events ?? []) {
    // not a model repair, but a design lane that shipped as a plain build: visible as its own label (no Designer editability)
    if (/^No design needed: keeping the plugin code as written/i.test(String(e?.message ?? ""))) { out.push(DESIGN_DOWNGRADE); continue; }
    const m = REPAIR_SAY.exec(String(e?.message ?? ""));
    if (!m) continue;
    const say = m[1].trim(), fix = Number(m[2]);
    if (/^Pre-check found/i.test(say)) {
      const rules = [...new Set((rec.precheck ?? []).filter((p) => p.attempt === fix && p.rule).map((p) => String(p.rule)))];
      out.push(...(rules.length ? rules : ["pre-check (unnamed rule)"]));
    } else if (/^Found \d+ known runtime problem/i.test(say)) {
      const rules = [...new Set((rec.precheck ?? []).filter((p) => p.attempt === fix && p.rule).map((p) => String(p.rule)))];
      out.push(...(rules.length ? rules.map((r) => `warning:${r}`) : ["runtime warning"]));
    } else if (/^Compiler found/i.test(say)) out.push("compile errors");
    else if (/^No design found/i.test(say)) out.push("No design found");
    else if (/^(Sound|Texture|Asset|Data pack|Creature|Design) check found/i.test(say)) out.push(`${say.replace(/ found .*$/i, "")} problems`);
    else if (/setup problem/i.test(say)) out.push("setup problems");
    else out.push(say.replace(/\d+/g, "N"));
  }
  return out;
}

const r2 = (n: number) => Math.round(n * 100) / 100;
const pct = (n: number, d: number) => (d ? Math.round((n / d) * 1000) / 10 : 0);
export function percentile(xs: number[], p: number): number {
  if (!xs.length) return 0;
  const a = [...xs].sort((x, y) => x - y), k = (a.length - 1) * p, f = Math.floor(k), c = Math.min(f + 1, a.length - 1);
  return a[f] + (a[c] - a[f]) * (k - f);
}

export type LaneStat = { lane: string; n: number; passAt1Pct: number; finalPassPct: number; repairShare: number; costUsd: number; p50: number; p80: number; p90: number };
export type JournalStats = {
  n: number; passAt1Pct: number; finalPassPct: number; fullPassPct: number; costUsd: number; repairedBuilds: number; repairedPct: number;
  repairSharePct: number; retryCostRatio: number | null; lanes: LaneStat[]; triggers: { trigger: string; repairs: number; builds: number }[];
};

export function journalStats(rows: StatRow[]): JournalStats {
  const n = rows.length;
  const cost = (rs: StatRow[]) => rs.reduce((a, r) => a + (r.costUsd || 0), 0);
  const repaired = rows.filter((r) => r.repairs > 0), clean = rows.filter((r) => r.repairs === 0 && r.pass);
  const total = cost(rows);
  const lanes = [...new Set(rows.map((r) => r.lane))].sort().map((lane) => {
    const rs = rows.filter((r) => r.lane === lane), c = rs.map((r) => r.costUsd || 0);
    return { lane, n: rs.length, passAt1Pct: pct(rs.filter((r) => r.firstAttempt).length, rs.length), finalPassPct: pct(rs.filter((r) => r.pass).length, rs.length), repairShare: r2(cost(rs.filter((r) => r.repairs > 0))), costUsd: r2(cost(rs)), p50: r2(percentile(c, 0.5)), p80: r2(percentile(c, 0.8)), p90: r2(percentile(c, 0.9)) };
  });
  const byTrig = new Map<string, { repairs: number; builds: Set<string> }>();
  for (const r of rows) for (const t of r.triggers ?? []) { const e = byTrig.get(t) ?? { repairs: 0, builds: new Set<string>() }; e.repairs++; e.builds.add(r.job); byTrig.set(t, e); }
  const triggers = [...byTrig.entries()].map(([trigger, e]) => ({ trigger, repairs: e.repairs, builds: e.builds.size })).sort((a, b) => b.repairs - a.repairs || a.trigger.localeCompare(b.trigger));
  const avg = (rs: StatRow[]) => (rs.length ? cost(rs) / rs.length : 0);
  return {
    n, passAt1Pct: pct(rows.filter((r) => r.firstAttempt).length, n), finalPassPct: pct(rows.filter((r) => r.pass).length, n), fullPassPct: pct(rows.filter((r) => r.full).length, n),
    costUsd: r2(total), repairedBuilds: repaired.length, repairedPct: pct(repaired.length, n), repairSharePct: pct(cost(repaired), total),
    retryCostRatio: clean.length && repaired.length ? r2(avg(repaired) / avg(clean)) : null, lanes, triggers,
  };
}

export function statsText(s: JournalStats, title = "eval journal"): string {
  const L: string[] = [];
  L.push(`${title}: ${s.n} builds, $${s.costUsd}`);
  L.push(`pass@1 ${s.passAt1Pct}%  final pass ${s.finalPassPct}%  full pass ${s.fullPassPct}%`);
  L.push(`repaired builds ${s.repairedBuilds} (${s.repairedPct}%) consumed ${s.repairSharePct}% of spend${s.retryCostRatio ? `; a repaired build costs ${s.retryCostRatio}x a clean one` : ""}`);
  L.push("", "lane      n   pass@1  final   $total  p50    p80    p90");
  for (const l of s.lanes) L.push(`${l.lane.padEnd(9)} ${String(l.n).padStart(3)}  ${String(l.passAt1Pct).padStart(5)}%  ${String(l.finalPassPct).padStart(5)}%  ${String(l.costUsd).padStart(6)}  ${l.p50.toFixed(2)}   ${l.p80.toFixed(2)}   ${l.p90.toFixed(2)}`);
  L.push("", "top repair triggers (repairs / builds)");
  if (!s.triggers.length) L.push("  none recorded (journal has no triggers: pass --builds <dir of <id>/build.json>)");
  for (const t of s.triggers.slice(0, 15)) L.push(`  ${String(t.repairs).padStart(3)} / ${String(t.builds).padStart(3)}  ${t.trigger}`);
  return L.join("\n");
}

export function compareText(a: JournalStats, b: JournalStats): string {
  const d = (x: number, y: number, unit = "") => `${x}${unit} -> ${y}${unit} (${y - x >= 0 ? "+" : ""}${r2(y - x)}${unit})`;
  return [`pass@1: ${d(a.passAt1Pct, b.passAt1Pct, "%")}`, `repaired builds: ${d(a.repairedPct, b.repairedPct, "%")}`, `repair share of spend: ${d(a.repairSharePct, b.repairSharePct, "%")}`, `cost per build: ${d(a.n ? r2(a.costUsd / a.n) : 0, b.n ? r2(b.costUsd / b.n) : 0)}`].join("\n");
}

