}

export function verdictMarkdown(v: GateVerdict): string {
  const m = (x: GateMetrics) => `${x.n} | ${x.finalPassPct ?? "-"}% | ${x.passAt1Pct ?? "-"}% | ${x.fullPassPct ?? "-"}% | $${x.costUsd} | ${x.costPerPass === null ? "-" : `$${x.costPerPass}`} | ${x.repairsPerBuild ?? "-"}`;
  const head = "| | builds | final pass | pass@1 | full | cost | cost/pass | repairs/build |\n|---|---|---|---|---|---|---|---|";
  return [
    `# Eval gate ${v.tag}: ${v.verdict.toUpperCase()}`, "",
    `${v.mode === "recorded" ? "Re-scored from a recorded journal" : v.mode === "real" ? "Real run through the build service" : "Dry run (nothing built)"}. Gate set v${v.setVersion}, ${v.coverage.scored}/${v.coverage.planned} jobs scored${v.image ? `, image ${
    ...v.reasons.map((r) => `- ${r}`), "",
    head, `| all | ${m(v.totals)} |`, ...Object.entries(v.byLane).map(([k, x]) => `| ${k} | ${m(x)} |`), "",
    ...v.compare.flatMap((c) => [`## vs ${c.against} (${c.ref}, ${c.common} common jobs)`, `final pass ${c.delta.finalPass ?? "-"} pts, pass@1 ${c.delta.passAt1 ?? "-"} pts, full ${c.delta.fullPass ?? "-"} pts, cost per pass x${c.costRatio ?? "-"}; regressions
  ].join("\n");
}
