const ENGINE_KEYS = new Set(["promptVersion", "sheets", "rulesVersion", "scannerHash", "imageDigest", "model", "toolchain", "revertOf", "import", "release", "scope", "moduleHashes", "tokens"]);

export function validateEngineRecord(raw: unknown): { ok: true; record: EngineRecord } | { ok: false; errors: SpecIssue[] } {
  if (raw === undefined || raw === null) return { ok: true, record: {} };
  if (typeof raw !== "object" || Array.isArray(raw)) return { ok: false, errors: [{ path: "engine", code: "not_object", message: "engine record must be an object" }] };
  const errors: SpecIssue[] = [];
  const r = raw as Record<string, unknown>;
  for (const k of Object.keys(r)) if (!ENGINE_KEYS.has(k)) errors.push({ path: `engine.${k}`, code: "unknown_field", message: `unknown engine record field ${k}` });
  for (const k of ["promptVersion", "rulesVersion", "scannerHash", "imageDigest", "model", "toolchain", "revertOf"]) {
    // toolchain lists every lane's tool (textures; sound; creature; item models; pack; datapack): a creature + sound +
    // texture build is over 200 characters, which used to make the whole revision (and the delivery) fail.
    const max = k === "toolchain" ? 1000 : 200;
    if (r[k] !== undefined && (typeof r[k] !== "string" || (r[k] as string).length > max)) errors.push({ path: `engine.${k}`, code: "bad_value", message: `${k} must be a string (max ${max})` });
  }
  if (r.sheets !== undefined) {
    const ok = Array.isArray(r.sheets) && r.sheets.length <= 50 && r.sheets.every((s) => s && typeof s === "object" && typeof (s as { name?: unknown }).name === "string" && ((s as { sha256?: unknown }).sha256 === undefined || SHA256.test(St
    if (!ok) errors.push({ path: "engine.sheets", code: "bad_value", message: "sheets must be up to 50 { name, sha256? } entries" });
  }
  if (r.import !== undefined) for (const m of validateImportMeta(r.import)) errors.push({ path: `engine.${m.split(":")[0]}`, code: "bad_import", message: m });
  for (const m of validateEngineReleaseField(r.release)) errors.push({ path: "engine.release", code: "bad_release", message: m });
  for (const m of validateScopeRecord(r)) errors.push({ path: `engine.${m.split(":")[0]}`, code: "bad_scope", message: m });
  return errors.length ? { ok: false, errors } : { ok: true, record: r as EngineRecord };
}
