// The real dependencies of lib/cyrus/assets/sync.ts (engine-core store + pack store from env). SERVER ONLY.
import { cyrusDb as db } from "../db";
import { addRevision, createProject, projectForRootBuild, recordAsset } from "../engine-core/store";
import { selectPackStore } from "../packhost/config";
import { selectRenderHost, soundLibraryCleared } from "../sound/host";
import { worldgenOn } from "../datapack/route";
import type { AssetSyncDeps } from "./sync";
import { currentStudioDoc } from "../studios/service";
import { candidateKeyOf, soundCandidateOf } from "../studios/marker";
import { currentStudioSound } from "../studios/sound-service";
import { studioCreatureOf } from "../modelstudio/creature-state";
import { handgunGripFixOn } from "../textures/display";
import { loadVanillaReference } from "../versions/vanilla/reference.server";
import { GATE_FLAG } from "../testflight/gate";

export function defaultAssetSyncDeps(env: Record<string, string | undefined> = process.env): AssetSyncDeps {
  return {
    selectStore: () => selectPackStore(env),
    // R42: vanilla checks. Fingerprints only where the PRIVATE reference dir is configured (never in production);
    // the pack validators ride the existing Test Flight switch.
    vanillaRefs: () => loadVanillaReference(env)?.fingerprints.map((f) => f.fp) ?? [],
    vanillaPackCheck: () => env[GATE_FLAG] === "1",
    projectForRootBuild: (root) => projectForRootBuild(root),
    createProject: (i) => createProject(i),
    findRevisionForBuild: (projectId, modBuildId) => db.cyrusRevision.findFirst({ where: { projectId, modBuildId }, orderBy: { seq: "asc" }, select: { id: true } }),
    headRevisionId: async (projectId) => (await db.cyrusProject.findUnique({ where: { id: projectId }, select: { headRevisionId: true } }))?.headRevisionId ?? null,
    addRevision: (projectId, input) => addRevision(projectId, input),
    recordAsset: (projectId, a) => recordAsset(projectId, a),
    // sound slice: OFF unless CYRUS_SOUND_RENDER=ssh; the library only with CYRUS_SOUND_LIBRARY_CLEARED=1
    selectRenderHost: () => selectRenderHost(env),
    soundLibraryCleared: () => soundLibraryCleared(env),
    // Texture Studio (R1b): keep studio edits a build did not replace (no studio rows exist until cyrus_studios_enabled)
    studioDocFor: async (projectId, name) => {
      const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { rootBuildId: true } });
      const root = p?.rootBuildId;
      const cands = root ? await db.modBuild.findMany({ where: { OR: [{ id: root }, { rootBuildId: root }], changeRequest: { startsWith: "Texture Studio edit of" } }, select: { id: true, changeRequest: true } }) : [];
      return currentStudioDoc({ assets: (pid) => db.cyrusProjectAsset.findMany({ where: { projectId: pid }, orderBy: { createdAt: "asc" }, take: 2000 }) }, projectId, name, new Set(cands.filter((c) => candidateKeyOf(c.changeRequest)).map((c) => c.id)));
    },
    worldgenOn: () => worldgenOn(env),
    // PROPOSED handgun grip fix: OFF until the owner approves (changes shipped packs for handgun textures)
    handgunGripFix: () => handgunGripFixOn(env),
    // Model Studio: keep cuboid-editor saves (and, from layer 1, creature paint) when the next build returns the creature
    studioCreatureFor: async (projectId, name) => studioCreatureOf(await db.cyrusProjectAsset.findMany({ where: { projectId, kind: "model", assetKey: name }, orderBy: { createdAt: "asc" }, take: 500 }), name),
    // Sound Studio (R1b): keep studio sound edits a build did not replace (no studio rows exist until the flag is on)
    studioSoundFor: async (projectId, set) => {
      const p = await db.cyrusProject.findUnique({ where: { id: projectId }, select: { rootBuildId: true } });
      const root = p?.rootBuildId;
      const cands = root ? await db.modBuild.findMany({ where: { OR: [{ id: root }, { rootBuildId: root }], changeRequest: { startsWith: "Sound Studio edit of" } }, select: { id: true, changeRequest: true } }) : [];
      const map = new Map(cands.flatMap((c) => { const x = soundCandidateOf(c.changeRequest); return x ? [[c.id, x] as const] : []; }));
      return currentStudioSound({ assets: (pid) => db.cyrusProjectAsset.findMany({ where: { projectId: pid }, orderBy: { createdAt: "asc" }, take: 2000 }) }, projectId, set, map);
    },
  };
}
