// Cyrus EVAL GATE: verdict maths (pass-rate deltas, cost ratio, regressions per lane, coverage), the recorded-journal mode on a
// fixture of the first measured run (eval first1: the 20 gate jobs), the engine release record per image, and the optional
// pre-promotion check in deploy-modbuilder.sh (failure path only: it must stop before touching the VM).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { execFileSync, spawnSync } from "node:child_process";
import { GATE_JOBS, GATE_KEYS, compareRuns, gateVerdict, metricsOf, rowsFromJournal, rowsFromReference, verdictMarkdown, type GateRow } from "../lib/cyrus/eval/gate";
import { loadEvalSet } from "../lib/cyrus/eval/set";
import { createManifest, imageGateStatus, recordImageVerdict, validateManifest } from "../lib/cyrus/learning/release-manifest";
import { treeComponents } from "../scripts/cyrus/eval-gate";

const FIX = path.join(__dirname, "fixtures/cyrus-eval-gate");
const journal = () => rowsFromJournal(fs.readFileSync(path.join(FIX, "journal.jsonl"), "utf8"));
const baseline = () => rowsFromReference(JSON.parse(fs.readFileSync(path.join(FIX, "baseline.json"), "utf8")));
const row = (job: string, lane: string, pass = true, firstAttempt = true, costUsd = 0.1, repairs = 0): GateRow => ({ job, lane, pass, firstAttempt, full: pass, costUsd, repairs });

describe("eval gate: the fixed subset", () => {
  it("20 prompts, every key in the eval set, every lane represented", () => {
    assert.equal(GATE_KEYS.length, 20);
    assert.equal(new Set(GATE_KEYS).size, 20);
    const set = new Map(loadEvalSet().map((p) => [p.key, p]));
    for (const k of GATE_KEYS) assert.ok(set.has(k), k);
    const lanes = new Set(journal().map((r) => r.lane));
    for (const l of ["plain", "texture", "sound", "designer"]) assert.ok(lanes.has(l), l);
  });
});

describe("eval gate: maths", () => {
  it("metrics: final pass, pass@1, cost per pass, repairs per build", () => {
    const m = metricsOf([row("a", "plain", true, true, 0.1), row("b", "plain", true, false, 0.3, 2), row("c", "plain", false, false, 0.2, 1), row("d", "plain", true, true, 0.2)]);
    assert.deepEqual([m.n, m.finalPassPct, m.passAt1Pct, m.costUsd, m.costPerPass, m.repairsPerBuild], [4, 75, 50, 0.8, 0.267, 0.75]);
    assert.equal(metricsOf([]).finalPassPct, null);
  });
  it("paired comparison: only common jobs, deltas in points, cost ratio, regressions per lane", () => {
    const ref = [row("a", "plain"), row("b", "plain"), row("c", "texture", true, false, 0.5, 1), row("x", "sound")];
    const now = [row("a", "plain", false, false, 0.2, 2), row("b", "plain", true, true, 0.05), row("c", "texture", true, true, 0.25), row("y", "sound")];
    const c = compareRuns(now, ref, "baseline", "ref");
    assert.equal(c.common, 3);
    assert.deepEqual(c.regressions, ["a"]);
    assert.deepEqual(c.byLane.plain.regressions, ["a"]);
    assert.equal(c.delta.finalPass, -33.3);
    assert.equal(c.delta.passAt1, 0);
    assert.equal(c.costRatio, 1.073, "$0.50 / 2 passes now vs $0.70 / 3 passes before");
    assert.deepEqual(c.firstTryLost, []);
  });
  it("verdicts: pass, warn on one regression, fail on two or on a cost blow-up, fail on low coverage, no-reference without refs", () => {
    const jobs = GATE_JOBS.slice(0, 10);
    const ref = jobs.map((j) => row(j, "plain"));
    const planned = jobs;
    assert.equal(gateVerdict({ tag: "t", mode: "recorded", rows: ref, refs: [{ against: "baseline", name: "b", rows: ref }], planned }).verdict, "pass");
    const one = ref.map((r, i) => (i === 0 ? { ...r, pass: false, firstAttempt: false } : r));
    const v1 = gateVerdict({ tag: "t", mode: "recorded", rows: one, refs: [{ against: "baseline", name: "b", rows: ref }], planned });
    assert.equal(v1.verdict, "warn");
    assert.match(v1.reasons.join(" "), /1 job\(s\) that passed in the accepted baseline fail now/);
    const two = ref.map((r, i) => (i < 2 ? { ...r, pass: false } : r));
    assert.equal(gateVerdict({ tag: "t", mode: "recorded", rows: two, refs: [{ against: "baseline", name: "b", rows: ref }], planned }).verdict, "fail");
    const dear = ref.map((r) => ({ ...r, costUsd: 0.2 }));
    const vc = gateVerdict({ tag: "t", mode: "recorded", rows: dear, refs: [{ against: "accepted", name: "g", rows: ref }], planned });

// Cyrus MOD PLANNER (live-test fix, item F): the LANES a mod request can need, and the planner's output contract.
// Pure + client-safe. The planner (a cheap Haiku call on the build service, services/modbuilder/planner.js, with the
// deterministic rules in ./rules.ts as the fallback) says which lanes the PROMPT implies; the deterministic capability
// router (./decide.ts) stays the authority on what can be built (game/version, plan, flags) and says why not.
import { z } from "zod";

export const LANES = [
  "texture", "itemStates", "sound", "model3d", "creature",
  "designItem", "designMenu", "designQuest", "designBoss", "designHud", "motion",
  "config", "datapack", "worldgen", "library",
] as const;
export type Lane = (typeof LANES)[number];
export const isLane = (v: unknown): v is Lane => typeof v === "string" && (LANES as readonly string[]).includes(v);

/** Customer wording per lane (what it creates). */
export const LANE_META: Record<Lane, { label: string; creates: string }> = {
  texture: { label: "Custom textures", creates: "item and block looks drawn for this mod" },
  itemStates: { label: "Item looks per state", creates: "a different look while pulling, aiming, charging or in a mode" },
  sound: { label: "Custom sounds", creates: "new sound effects or music with subtitles" },
  model3d: { label: "3D models", creates: "shaped 3D looks beyond a flat item" },
  creature: { label: "Animated creature models", creates: "an animated custom mob model and skin" },
  designItem: { label: "Item with abilities", creates: "a typed item design: triggers, cooldowns, effects" },
  designMenu: { label: "Menus", creates: "chest-menu GUIs, shops and dialogues" },
  designQuest: { label: "Quests", creates: "objectives, chains, daily tasks and rewards" },
  designBoss: { label: "Boss fight", creates: "phases, telegraphed attacks, waves, a boss bar" },
  designHud: { label: "HUD", creates: "glyph bars and icons in the action bar, boss bar or sidebar" },
  motion: { label: "Animated props", creates: "doors, hatches, turrets and moving display-entity props" },
  config: { label: "Settings", creates: "editable tunables (damage, cooldowns, messages) in config.yml" },
  datapack: { label: "Data pack", creates: "recipes, loot tables, advancements, tags" },
  worldgen: { label: "World generation", creates: "biomes, structures, a dimension" },
  library: { label: "Library assets", creates: "ready-made sounds or textures from the Nxeon library" },
};

const LaneVerdict = z.object({
  need: z.boolean(),
  why: z.string().max(240).default(""),
  confidence: z.number().min(0).max(1).default(0.5),
});
/** What the planner model must answer: one verdict per lane it mentions (missing lanes = not needed). */
export const PlannerOutput = z.object({ lanes: z.record(z.string(), LaneVerdict) });
export type LaneNeed = { lane: Lane; need: boolean; why: string; confidence: number };
export type PlannerSource = "planner" | "rules";
export type Needs = { source: PlannerSource; lanes: LaneNeed[]; costUsd?: number; ms?: number; error?: string };

/** Parse + validate the planner model's text (it may wrap the JSON in a code fence). Null = invalid: use the rules. */
export function parsePlannerText(raw: unknown): LaneNeed[] | null {
  if (typeof raw !== "string" || !raw.trim()) return null;
  const s = raw.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
  const a = s.indexOf("{"), b = s.lastIndexOf("}");
  if (a < 0 || b <= a) return null;
  let json: unknown;
  try { json = JSON.parse(s.slice(a, b + 1)); } catch { return null; }
  const p = PlannerOutput.safeParse(json);
  if (!p.success) return null;
  const out: LaneNeed[] = [];
  for (const lane of LANES) {
    const v = p.data.lanes[lane];
    out.push(v ? { lane, need: v.need, why: v.why.slice(0, 200), confidence: Math.round(v.confidence * 100) / 100 } : { lane, need: false, why: "", confidence: 0.5 });
  }
  return out;
