// Offline "portal sync" check of one eval result (task: metric honesty). An eval build bypasses the portal, so nothing
// proves the portal could have SAVED it. This runs the same validators the real sync (lib/cyrus/assets/sync.ts) runs:
//   - every returned texture / sound / creature / data pack / design through its checkReturned* validator (an asset the portal
//     would drop is a failure here: the service shipped it, the customer would never see it)
//   - the engine record the sync writes onto the revision through validateEngineRecord (the goblin bug: engine.toolchain
//     over the limit made the whole revision fail and the build stuck)
// Pure apart from rendering (textures render in process, as in the portal). No network, no database.
import { validateEngineRecord } from "../engine-core/revisions";
import { checkReturnedTexture } from "../assets/textures";
import { checkReturnedSound } from "../assets/sounds";
import { checkReturnedCreatures } from "../creature/portal";
import { checkReturnedDatapacks } from "../datapack/sync";
import { checkReturnedDesigns } from "../designer/sync";
import { QUALITY_VERSION } from "../textures/quality";
import { COMPILER_VERSION } from "../creature/compile";
import { SKIN_QUALITY_VERSION } from "../creature/quality";
import { EMITTER_VERSION } from "../datapack/emit";
import { ITEMMODEL_EMITTER_VERSION } from "../itemmodel/emit";

export type SyncStatus = "pass" | "fail" | "not_run";
export type SyncCheck = { status: SyncStatus; detail: string; problems: string[] };

type Rec = {
  status: string; assetResult?: Record<string, unknown> | null; promptVersion?: string | null; model?: string | null; pluginName?: string | null;
};
const arr = (v: unknown): Record<string, unknown>[] => (Array.isArray(v) ? (v as Record<string, unknown>[]) : []);

/** The toolchain string the sync would write for these assets (same parts, same 1000-character clip as assets/sync.ts). */
export function simulatedToolchain(ar: Record<string, unknown>, mcVersion: string, counts: { textures: number; sounds: number; creatures: number; datapacks: number; itemModels: number; packed: boolean }): string {
  return [
    ...(counts.textures ? [`cyrus-textures ${QUALITY_VERSION} (service ${String(ar.qualityVersion ?? "?")})`] : []),
    ...(counts.sounds ? ["cyrus-sound render-1/quality-1 on render-host (ffmpeg version 6.1.1-3ubuntu5.1)"] : []),
    ...(counts.creatures ? [`cyrus-creature ${COMPILER_VERSION}/${SKIN_QUALITY_VERSION} (bbmodel 5.0 for BetterModel 3.5.0)`] : []),
    ...(counts.packed && counts.itemModels ? [`${ITEMMODEL_EMITTER_VERSION}`] : []),
    ...(counts.packed ? ["pack format 55"] : []),
    ...(counts.datapacks ? [`cyrus-datapack ${EMITTER_VERSION} data pack format 94.1 for ${mcVersion}`] : []),
  ].join("; ").slice(0, 1000);
}

export function portalSyncCheck(rec: Rec | null, ctx: { namespace: string; mcVersion: string; worldgen?: boolean }): SyncCheck {
  if (!rec || rec.status !== "succeeded") return { status: "not_run", detail: "the build did not succeed: nothing to sync", problems: [] };
  const problems: string[] = [];
  const ar = (rec.assetResult ?? {}) as Record<string, unknown>;
  let okTextures = 0, okSounds = 0, okCreatures = 0, okPacks = 0;
  const guard = (what: string, f: () => void) => { try { f(); } catch (e) { problems.push(`${what}: validator threw ${(e as Error).message.slice(0, 120)}`); } };
  guard("textures", () => {
    for (const t of arr(ar.textures)) {
      const c = checkReturnedTexture({ name: t.name, spec: t.spec });
      if (c.ok) okTextures++; else problems.push(`texture ${c.name}: ${c.reason.slice(0, 140)}`);
    }
  });
  guard("sounds", () => {
    for (const s of arr(ar.sounds)) {
      const c = checkReturnedSound({ key: String(s.key ?? s.set ?? "?"), spec: s.spec } as Parameters<typeof checkReturnedSound>[0], { library: false });
      if (c.ok) okSounds++; else problems.push(`sound ${c.set}: ${c.reason.slice(0, 140)}`);
    }
  });
  guard("creatures", () => {
    if (!arr(ar.creatures).length) return;
    const c = checkReturnedCreatures(arr(ar.creatures) as { name?: unknown; spec?: unknown }[], ctx.namespace);
    okCreatures = c.ok.length;
    for (const d of c.dropped) problems.push(`creature ${d.name}: ${d.reason.slice(0, 140)}`);
  });
  guard("datapacks", () => {
    if (!arr(ar.datapacks).length) return;
    const c = checkReturnedDatapacks(arr(ar.datapacks) as never, { namespace: ctx.namespace, mcVersion: ctx.mcVersion, worldgen: ctx.worldgen !== false });
    okPacks = c.ok.length;
    for (const d of c.dropped) problems.push(`data pack ${d.name}: ${d.reason.slice(0, 140)}`);
  });
  guard("designs", () => {
    if (!arr(ar.designs).length) return;
    const c = checkReturnedDesigns(arr(ar.designs) as never, { namespace: ctx.namespace, mcVersion: ctx.mcVersion, pluginName: rec.pluginName ?? null, compile: ar.designCompile as never });
    for (const d of c.dropped) problems.push(`design ${d.name}: ${d.reason.slice(0, 140)}`);
  });
  const toolchain = simulatedToolchain(ar, ctx.mcVersion, { textures: okTextures, sounds: okSounds, creatures: okCreatures, datapacks: okPacks, itemModels: arr(ar.itemModels).length, packed: okTextures + okSounds > 0 });
  const engine = validateEngineRecord({ ...(rec.promptVersion ? { promptVersion: rec.promptVersion } : {}), ...(rec.model ? { model: rec.model } : {}), toolchain });
  if (!engine.ok) for (const e of engine.errors) problems.push(`engine record: ${e.message}`);
  if (problems.length) return { status: "fail", detail: problems.join("; ").slice(0, 400), problems };
  return { status: "pass", detail: `engine record valid (toolchain ${toolchain.length} chars); ${okTextures} textures, ${okSounds} sounds, ${okCreatures} creatures, ${okPacks} data packs checked`, problems };
}
