cat > lib/cyrus/eval/realpass.ts <<'E'
// Cyrus eval METRIC HONESTY (owner bug, goblin mod): "boot" only said the Paper server started, so a plugin that could not
// enable (missing depend: BetterModel) counted as a boot pass, and a build the portal could not save still counted as a
// success. The stages below are SEPARATE and explicit; "real pass" is the number a customer would actually experience:
//
//   REAL PASS = the service built it AND the plugin enabled in the Test Flight AND every planned lane shipped AND the
//               portal could save it (engine record + asset validators, offline).
//
// A stage that did not run is "not_run" and never a pass: a build that was not flown is NOT a real pass (it is counted as
// "unverified" so the headline cannot be inflated by skipping the flight). Pure.
import type { FlightOutcome, Stage, StageStatus } from "./score";
import type { SyncCheck } from "./sync-check";

export const REAL_STAGES = ["compiled", "scanned", "booted", "pluginEnabled", "commands", "assets", "portalSync"] as const;
export type RealStageId = (typeof REAL_STAGES)[number];
export const REAL_STAGE_LABEL: Record<RealStageId, string> = {
  compiled: "compiled", scanned: "scanned", booted: "server booted", pluginEnabled: "plugin enabled", commands: "commands registered", assets: "assets delivered", portalSync: "portal sync ok",
};

export type RealStages = Record<RealStageId, Stage>;
export type RealVerdict = {
  stages: RealStages;
  /** the honest pass (see the file header) */
  realPass: boolean;
  /** real pass AND no model repair was needed */
  realFirst: boolean;
  /** the build succeeded but the Test Flight did not run (or did not reach the plugin check): cannot be a real pass */
  unverified: boolean;
  /** the first stage that blocks the real pass ("" when it is one) */
  blocker: RealStageId | "refused" | "infra" | "";
};

type RealInput = {
  status: string; errorCode?: string | null; lane: string; repairs: number; infra?: boolean; pass: boolean;
  stages: Record<string, Stage>; flight: FlightOutcome | null; sync?: SyncCheck | null; mustRefuse?: boolean;
};

const st = (status: StageStatus, detail = ""): Stage => ({ status, detail });
const norm = (s: string | undefined): StageStatus => (s === "pass" ? "pass" : s === "fail" ? "fail" : s === "n/a" ? "n/a" : "not_run");

/** The Test Flight check with this id, or null when the flight did not report it. */
export const flightCheck = (f: FlightOutcome | null, id: string) => (f?.checks ?? []).find((c) => c.id === id) ?? null;

export function realVerdict(r: RealInput): RealVerdict {
  const S = r.stages;
  const f = r.flight;
  const ok = r.status === "succeeded";
  const empty = (d: string): RealStages => Object.fromEntries(REAL_STAGES.map((k) => [k, st("n/a", d)])) as RealStages;
  if (r.mustRefuse) return { stages: empty("must-refuse prompt"), realPass: r.pass, realFirst: r.pass, unverified: false, blocker: r.pass ? "" : "refused" };
  const stages = empty("");
  stages.compiled = S.compile ? { ...S.compile, status: norm(S.compile.status) } : st("not_run");
  stages.scanned = S.scan ? { ...S.scan, status: norm(S.scan.status) } : st("not_run");
  if (!ok) {
    for (const k of ["booted", "pluginEnabled", "commands", "assets", "portalSync"] as const) stages[k] = st("not_run", `build ${r.errorCode ?? r.status}`);
    return { stages, realPass: false, realFirst: false, unverified: false, blocker: r.infra ? "infra" : stages.compiled.status === "fail" ? "compiled" : stages.scanned.status === "fail" ? "scanned" : "compiled" };
  }
  // booted: the server process started (Test Flight boot_done). NOT proof the plugin works.
  const boot = flightCheck(f, "boot");
  stages.booted = boot ? st(norm(boot.status), boot.detail) : !f ? st("not_run", "Test Flight was not requested") : f.verdict === "not_run" ? st("not_run", f.reason ?? "not flown") : st(f.verdict === "passed" ? "pass" : "not_run", f.label ?? "");
  const pe = flightCheck(f, "plugins_enabled");
  if (pe) stages.pluginEnabled = st(norm(pe.status), pe.detail);
  else if (r.lane === "datapack" && (!f || f.verdict === "not_run")) stages.pluginEnabled = st("n/a", "data pack only: no plugin to enable");
  else stages.pluginEnabled = f && f.verdict === "passed" ? st("pass", "Test Flight passed (no per-check record)") : st("not_run", f?.reason ?? "no Test Flight: plugin enable not verified");
  const cr = flightCheck(f, "commands_registered");
  stages.commands = cr ? st(norm(cr.status), cr.detail) : st("not_run", "no command check");
  stages.assets = S.assets ? { ...S.assets, status: norm(S.assets.status) } : st("n/a");
  const sy = r.sync;
  stages.portalSync = sy ? st(sy.status, sy.detail) : st("not_run", "offline sync check not recorded (journal predates it)");
  // Real pass: plugin enabled (or data-pack-only n/a), lanes shipped (pass or n/a), portal sync not failing. A sync that
  // was never computed (old journals) does not block, but is visible as not_run in the table.
  const peOk = stages.pluginEnabled.status === "pass" || (stages.pluginEnabled.status === "n/a" && r.lane === "datapack");
  const assetsOk = stages.assets.status === "pass" || stages.assets.status === "n/a";
  const syncOk = stages.portalSync.status !== "fail";
  const realPass = peOk && assetsOk && syncOk;
  const unverified = !peOk && stages.pluginEnabled.status === "not_run";
  const blocker: RealVerdict["blocker"] = realPass ? "" : !peOk ? "pluginEnabled" : !assetsOk ? "assets" : "portalSync";
  return { stages, realPass, realFirst: realPass && r.repairs === 0, unverified, blocker };
}

/** Counts per stage over verdicts (pass / fail / not run / n/a). */
export function stageCounts(vs: RealVerdict[]): Record<RealStageId, { pass: number; fail: number; notRun: number; na: number }> {
  const out = Object.fromEntries(REAL_STAGES.map((k) => [k, { pass: 0, fail: 0, notRun: 0, na: 0 }])) as Record<RealStageId, { pass: number; fail: number; notRun: number; na: number }>;
  for (const v of vs) for (const k of REAL_STAGES) { const s = v.stages[k].status; if (s === "pass") out[k].pass++; else if (s === "fail") out[k].fail++; else if (s === "not_run") out[k].notRun++; else out[k].na++; }
  return out;
}
