// Failure taxonomy of an eval run: every build that is NOT a real pass gets exactly one primary class, so a run prints a ranked
// table of WHY builds fail (classes seen so far: tracker 97-110). Pure; reads the journal result fields only.
import type { Stage } from "./score";
import { realOfResult } from "./realpass";

export const FAILURE_CLASSES = [
  "timeout_limit", "budget_cap", "false_refusal", "perf_guard", "compile", "safety_scan", "plugin_missing_depend", "plugin_not_enabled",
  "design_none", "texture_check", "asset_check", "sync_engine_record", "commands_not_registered", "not_flown", "other",
] as const;
export type FailureClass = (typeof FAILURE_CLASSES)[number];
export const FAILURE_LABEL: Record<FailureClass, string> = {
  timeout_limit: "timeout / session limit / service unavailable", budget_cap: "budget cap", false_refusal: "false refusal", perf_guard: "performance guard (repairs exhausted)",
  compile: "compile error", safety_scan: "safety scan blocked", plugin_missing_depend: "plugin did not enable: missing depend / engine class",
  plugin_not_enabled: "plugin did not enable (other)", design_none: "design lane: no design shipped", texture_check: "texture check failed",
  asset_check: "asset check failed (sound / data pack / creature / other)", sync_engine_record: "portal sync / engine record invalid", commands_not_registered: "commands not registered",
  not_flown: "built, but not flown (plugin enable unverified)", other: "other / unclassified",
};

export type TaxonomyInput = {
  status: string; errorCode?: string | null; lane: string; repairs?: number; infra?: boolean; pass?: boolean; triggers?: string[];
  stages?: Record<string, Stage>; flight?: { verdict?: string; checks?: { id: string; status: string; detail: string }[]; reason?: string | null } | null;
  real?: Parameters<typeof realOfResult>[0]["real"];
};

const INFRA = new Set(["ai_unavailable", "unavailable", "timeout", "internal", "interrupted", "cancelled", "bad_request"]);
const DEPEND = /depend|BetterModel|UnknownDependency|NoClassDefFound|ClassNotFound|engine plugin|could not load/i;

/** Primary failure class of a result, or null when it is a real pass. */
export function classifyFailure(r: TaxonomyInput): FailureClass | null {
