  if (failed && trig.some((t) => /^(warning:)?perf-/.test(t))) return "perf_guard";
  if (code === "compile" || S.compile?.status === "fail") return "compile";
  if (code === "safety" || S.scan?.status === "fail") return "safety_scan";
  if (failed) return "other";
  const flightPe = (r.flight?.checks ?? []).find((c) => c.id === "plugins_enabled");
  if (real.stages.pluginEnabled === "fail") return DEPEND.test(`${flightPe?.detail ?? ""} ${S.boot?.detail ?? ""}`) ? "plugin_missing_depend" : "plugin_not_enabled";
  const ad = `${S.assets?.detail ?? ""}`;
  if (real.stages.assets === "fail") {
    if (/design/i.test(ad) || trig.includes("No design found")) return "design_none";
    if (/texture/i.test(ad) || trig.some((t) => /^Texture check/i.test(t))) return "texture_check";
    return "asset_check";
  }
  if (real.stages.portalSync === "fail") return "sync_engine_record";
  if (real.stages.commands === "fail") return "commands_not_registered";
  if (real.unverified) return "not_flown";
  return "other";
}

export type TaxonomyRow = { cls: FailureClass; label: string; builds: number; share: number; jobs: string[] };
/** Ranked failure table (most frequent first) over rows with a `job`. */
export function rankFailures(rows: (TaxonomyInput & { job: string })[]): { failed: number; table: TaxonomyRow[] } {
