// Live eval verdict for the launch check: reads eval run directories (<dir>/<tag>/journal.jsonl, written by
// scripts/cyrus/eval-run.ts) and summarises the newest COMPLETED run plus, separately, a run still in progress.
// PURE file reads. Completed = every planned job has a result, or the run stopped for budget, or a report/baseline/gate file exists.
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

const pct = (n, d) => (d > 0 ? Math.round((n / d) * 1000) / 10 : null);
const usd = (n) => Math.round(n * 100) / 100;

/** journal text -> { plan, results (last result per job, infra excluded), budgetStop }. */
export function parseJournal(text) {
  let plan = null, budgetStop = false;
  const last = new Map();
  for (const line of String(text).split("\n")) {
    if (!line.trim()) continue;
    let j; try { j = JSON.parse(line); } catch { continue; }
    if (j.t === "plan") plan = { tag: j.tag, model: j.model, jobs: Array.isArray(j.jobs) ? j.jobs : [] };
    else if (j.t === "budget_stop") budgetStop = true;
    else if (j.t === "done" && j.job && j.result) last.set(j.job, j.result);
  }
  return { plan, budgetStop, results: [...last.values()] };
}

export function summarizeResults(results) {
  const real = results.filter((r) => !r.infra);
  const n = real.length;
  const passed = real.filter((r) => r.pass);
  const first = real.filter((r) => r.firstAttempt);
  const booted = real.filter((r) => r.flight?.verdict === "passed" || r.stages?.boot?.status === "pass");
  const attempted = real.filter((r) => r.pass).length || 0;
  const cost = real.reduce((a, r) => a + (r.costUsd || 0), 0);
  const repaired = real.filter((r) => (r.repairs || 0) > 0 || (r.pass && !r.firstAttempt));
  const repairCost = repaired.reduce((a, r) => a + (r.costUsd || 0), 0);
  const failing = real.filter((r) => !r.pass).map((r) => ({ job: r.job, lane: r.lane, status: r.status, errorCode: r.errorCode ?? null }));
  const repairedJobs = repaired.filter((r) => r.pass).map((r) => ({ job: r.job, lane: r.lane, triggers: r.triggers || [] }));
  return {
    builds: n, infraExcluded: results.length - n,
    passAt1Pct: pct(first.length, n), finalPassPct: pct(passed.length, n), bootPct: pct(booted.length, passed.length || n),
    repairSharePct: cost > 0 ? pct(repairCost, cost) : null, costUsd: usd(cost), costPerPassUsd: attempted ? usd(cost / attempted) : null,
    failing, repaired: repairedJobs,
  };
}

/** Newest run directory with a journal: { tag, complete, planned, done, at, ...summary } or null. */
export function latestRuns(evalDir) {
  const runs = [];
  let dirs = []; try { dirs = readdirSync(evalDir); } catch { return { completed: null, inProgress: null }; }
  for (const d of dirs) {
    const jp = join(evalDir, d, "journal.jsonl");
    if (!existsSync(jp)) continue;
    let text; try { text = readFileSync(jp, "utf8"); } catch { continue; }
    const { plan, budgetStop, results } = parseJournal(text);
    if (!plan || results.length === 0) continue;
    const planned = plan.jobs.length;
    const done = new Set(results.map((r) => r.job)).size;
    const hasReport = ["report.md", "baseline.json", "gate.json"].some((f) => existsSync(join(evalDir, d, f)));
    const complete = budgetStop || hasReport || (planned > 0 && done >= planned);
    runs.push({ tag: d, complete, planned, done, at: new Date(statSync(jp).mtimeMs).toISOString(), model: plan.model, ...summarizeResults(results) });
  }
  runs.sort((a, b) => Date.parse(b.at) - Date.parse(a.at));
  return { completed: runs.find((r) => r.complete) || null, inProgress: runs.find((r) => !r.complete) || null };
}
  if (best) { try { const v = JSON.parse(readFileSync(best.p, "utf8")); if (v.schema === "cyrus-eval-gate-1") f.eval = { ...f.eval, at: v.createdAt, verdict: v.verdict, finalPassPct: v.totals?.finalPassPct ?? null, passAt1Pct: v.totals?.passAt1Pct ?? null }; } catch { /* ignore */ } }

  // ---- eval
  const ev = f.eval;
  if (ev) {
    if (!ev.at) add(row("eval", "Quality", "Latest eval verdict", S.WARN, `no gate verdict found${ev.baselineExists ? "" : "; services/modbuilder/eval/baseline.json is not in the repo"}`, "Run scripts/cyrus/eval-gate-weekly.sh with CYRUS_EVAL_GATE_BUDGET_USD set (about $8), then accept the run as the baseline."));
    else {
      const a = ageMs(ev.at, f.now);
      const old = a !== null && a > T.evalFailDays * DAY ? S.FAIL : a !== null && a > T.evalWarnDays * DAY ? S.WARN : S.PASS;
      const low = ev.finalPassPct !== null && ev.finalPassPct < T.evalMinFinalPassPct ? S.FAIL : ev.verdict === "fail" ? S.FAIL : ev.verdict === "warn" || ev.verdict === "no-reference" ? S.WARN : S.PASS;
      const worst = ORDER.indexOf(old) <= ORDER.indexOf(low) ? old : low;
      add(publicOnly("eval", "Quality", "Latest eval verdict", worst,
        `verdict=${ev.verdict}, final pass ${ev.finalPassPct ?? "?"}% (min ${T.evalMinFinalPassPct}), pass@1 ${ev.passAt1Pct ?? "?"}%, ${a === null ? "age unknown" : days(a) + " d old"}`,
        worst === S.PASS ? "" : "Re-run the eval gate against the live image and review the regressions before launch."));
    }
  }
  // ---- live eval journals (newest completed run from /root/cyrus-eval/<tag>/journal.jsonl; works without a gate.json)
  const er = f.evalRuns;
  if (er) {
    const c = er.completed, ip = er.inProgress;
    if (!c) add(row("eval-run", "Quality", "Newest completed eval run", S.WARN, ip ? `none completed; ${ip.tag} in progress (${ip.done}/${ip.planned})` : "no eval journal found", "Run scripts/cyrus/eval-run.ts (docs/cyrus/07-operations.md: eval baseline acceptance) against the live image."));
    else {
      const a = ageMs(c.at, f.now);
      const old = a !== null && a > T.evalFailDays * DAY ? S.FAIL : a !== null && a > T.evalWarnDays * DAY ? S.WARN : S.PASS;
      const low = c.finalPassPct !== null && c.finalPassPct < T.evalMinFinalPassPct ? S.FAIL : c.passAt1Pct !== null && c.passAt1Pct < T.evalMinPassAt1Pct ? S.WARN : c.bootPct !== null && c.bootPct < 95 ? S.WARN : S.PASS;
      const worst = ORDER.indexOf(old) <= ORDER.indexOf(low) ? old : low;
      add(publicOnly("eval-run", "Quality", "Newest completed eval run", worst,
        `${c.tag}: ${c.builds} builds, pass@1 ${c.passAt1Pct ?? "?"}%, final ${c.finalPassPct ?? "?"}%, boot ${c.bootPct ?? "?"}%, repair share ${c.repairSharePct ?? "?"}%, $${c.costUsd}${a === null ? "" : `, ${days(a)} d old`}${c.failing.length ? `; failing: ${c.failing.slice(0, 5).map((x) => x.job).join(", ")}` : ""}`,
        worst === S.PASS ? "" : "Review the failing prompts (scripts/cyrus/eval-journal-stats.ts <run dir>) and re-run against the live image."));
    }
    if (ip) add(row("eval-run-live", "Quality", "Eval run in progress", S.INFO, `${ip.tag}: ${ip.done}/${ip.planned} builds, pass@1 ${ip.passAt1Pct ?? "?"}%, final ${ip.finalPassPct ?? "?"}%, boot ${ip.bootPct ?? "?"}%, $${ip.costUsd} so far`, ""));
  }
  return rows;
}

