cd /tank/dev-worktrees/cyrus-eval-real && cat > test/cyrus-eval-realism.test.ts <<'E'
// Cyrus eval REALISM (2026-10-14): honest stages + real pass, offline portal-sync check, failure taxonomy, the real-world corpus and
// its presets, gate backward compatibility. Origin: the goblin mod counted as a boot pass although its plugin could not enable.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { realOfResult, realVerdict } from "../lib/cyrus/eval/realpass";
import { portalSyncCheck } from "../lib/cyrus/eval/sync-check";
import { classifyFailure, rankFailures } from "../lib/cyrus/eval/taxonomy";
import { journalStats, statsText, type StatRow } from "../lib/cyrus/eval/stats";
import { assetsRequest, laneOf, loadEvalSet, loadMatrix, loadRealWorld } from "../lib/cyrus/eval/set";
import { planRun } from "../lib/cyrus/eval/run";
import { compareRuns, gateVerdict, metricsOf, rowsFromJournal, rowsFromReference, type GateRow } from "../lib/cyrus/eval/gate";
import { validateEngineRecord } from "../lib/cyrus/engine-core/revisions";
import { summarizeResults } from "../scripts/cyrus/lib/eval-run.mjs";

const st = (status: string, detail = "") => ({ status, detail }) as never;
const stages = (o: Record<string, [string, string?]> = {}) => ({ compile: st("pass"), scan: st("pass"), refused: st("n/a"), assets: st("n/a"), quality: st("n/a"), boot: st("pass"), playtest: st("not_run"), ...Object.fromEntries(Object.entries(o).map(([k, [s, d]]) => [k, st(s, d)])) });
const flight = (checks: Record<string, string>, verdict = "passed") => ({ verdict, label: null, checks: Object.entries(checks).map(([id, status]) => ({ id, status, detail: id === "plugins_enabled" && status === "fail" ? "Goblin: UnknownDependencyException BetterModel" : "" })) }) as never;
const base = { status: "succeeded", lane: "creature", repairs: 0, pass: true };

describe("real pass: stages are separate and honest", () => {
  it("goblin shape: server booted but the plugin did not enable -> NOT a real pass, booted still reported", () => {
    const v = realVerdict({ ...base, stages: stages({ assets: ["pass"] }), flight: flight({ boot: "pass", plugins_enabled: "fail" }, "failed"), sync: null });
    assert.equal(v.stages.booted.status, "pass");
    assert.equal(v.stages.pluginEnabled.status, "fail");
    assert.equal(v.realPass, false);
    assert.equal(v.blocker, "pluginEnabled");
  });
  it("not flown is never a real pass (unverified), a flown clean build with shipped lanes is", () => {
    const nf = realVerdict({ ...base, stages: stages({ assets: ["pass"], boot: ["not_run"] }), flight: null });
    assert.equal(nf.realPass, false);
    assert.equal(nf.unverified, true);
    const ok = realVerdict({ ...base, stages: stages({ assets: ["pass"] }), flight: flight({ boot: "pass", plugins_enabled: "pass", commands_registered: "pass" }), sync: { status: "pass", detail: "", problems: [] } });
    assert.equal(ok.realPass, true);
    assert.equal(ok.realFirst, true);
    assert.equal(realVerdict({ ...base, repairs: 1, stages: stages({ assets: ["pass"] }), flight: flight({ boot: "pass", plugins_enabled: "pass" }) }).realFirst, false);
  });
  it("a lane that did not ship, or a portal sync failure, blocks the real pass even when the plugin enabled", () => {
    const f = flight({ boot: "pass", plugins_enabled: "pass" });
    const a = realVerdict({ ...base, lane: "texture", stages: stages({ assets: ["fail", "nothing shipped for textures"] }), flight: f });
    assert.equal(a.realPass, false); assert.equal(a.blocker, "assets");
    const s = realVerdict({ ...base, stages: stages({ assets: ["pass"] }), flight: f, sync: { status: "fail", detail: "engine record: toolchain must be a string (max 200)", problems: [] } });
    assert.equal(s.realPass, false); assert.equal(s.blocker, "portalSync");
  });
  it("derives from an old journal result (no real block); portal sync stays not_run", () => {
    const r = realOfResult({ ...base, stages: stages({ assets: ["pass"] }) as never, flight: flight({ boot: "pass", plugins_enabled: "pass" }) });
    assert.equal(r.realPass, true);
    assert.equal(r.stages.portalSync, "not_run");
  });
});

describe("portal sync offline check", () => {
  it("a failed build is not_run; a plain succeeded build passes with a valid engine record", () => {
    assert.equal(portalSyncCheck({ status: "failed" }, { namespace: "nx_aaaaaaaa", mcVersion: "1.21.11" }).status, "not_run");
    const r = portalSyncCheck({ status: "succeeded", promptVersion: "p-1", model: "m" }, { namespace: "nx_aaaaaaaa", mcVersion: "1.21.11" });
    assert.equal(r.status, "pass");
  });
  it("a texture the portal would refuse is a sync failure", () => {
    const r = portalSyncCheck({ status: "succeeded", assetResult: { textures: [{ name: "ruby", spec: { not: "a spec" } }] } }, { namespace: "nx_aaaaaaaa", mcVersion: "1.21.11" });
    assert.equal(r.status, "fail");
    assert.match(r.detail, /texture ruby/);
  });
  it("the goblin engine record: a 300-char toolchain is valid now, an over-limit one is rejected", () => {
    assert.equal(validateEngineRecord({ toolchain: "x".repeat(300) }).ok, true);
    assert.equal(validateEngineRecord({ toolchain: "x".repeat(1001) }).ok, false);
    assert.equal(validateEngineRecord({ promptVersion: "x".repeat(201) }).ok, false);
  });
});

describe("failure taxonomy", () => {
  const t = (o: Record<string, unknown>) => classifyFailure({ status: "succeeded", lane: "plain", repairs: 0, pass: true, stages: stages() as never, flight: flight({ boot: "pass", plugins_enabled: "pass" }), ...o } as never);
  it("classes", () => {
    assert.equal(t({}), null);
    assert.equal(t({ status: "failed", errorCode: "compile", pass: false, stages: stages({ compile: ["fail"] }) }), "compile");
    assert.equal(t({ status: "failed", errorCode: "compile", pass: false, triggers: ["perf-spawn-in-loop"], stages: stages({ compile: ["fail"] }) }), "perf_guard");
    assert.equal(t({ status: "failed", errorCode: "ai_unavailable", pass: false }), "timeout_limit");
    assert.equal(t({ status: "failed", errorCode: "timeout", pass: false }), "timeout_limit");
    assert.equal(t({ status: "failed", errorCode: "budget", pass: false }), "budget_cap");
    assert.equal(t({ flight: flight({ boot: "pass", plugins_enabled: "fail" }, "failed") }), "plugin_missing_depend");
    assert.equal(t({ lane: "designer", stages: stages({ assets: ["fail", "nothing shipped for designs"] }) }), "design_none");
    assert.equal(t({ lane: "texture", stages: stages({ assets: ["fail", "nothing shipped for textures"] }) }), "texture_check");
    assert.equal(t({ lane: "sound", stages: stages({ assets: ["fail", "nothing shipped for sounds"] }) }), "asset_check");
    assert.equal(t({ real: { realPass: false, realFirst: false, unverified: false, stages: { pluginEnabled: { status: "pass", detail: "" }, assets: { status: "n/a", detail: "" }, portalSync: { status: "fail", detail: "engine" } } } }), "sync_engine_record");
    assert.equal(t({ stages: stages({ boot: ["not_run"] }), flight: null }), "not_flown");
  });
  it("ranked table counts the primary class once per build", () => {
    const rows = [
      { job: "a", status: "failed", errorCode: "compile", lane: "plain", pass: false, stages: stages({ compile: ["fail"] }) },
      { job: "b", status: "failed", errorCode: "compile", lane: "plain", pass: false, stages: stages({ compile: ["fail"] }) },
      { job: "c", status: "failed", errorCode: "timeout", lane: "plain", pass: false },
      { job: "d", status: "succeeded", lane: "plain", pass: true, repairs: 0, stages: stages(), flight: flight({ boot: "pass", plugins_enabled: "pass" }) },
    ];
    const r = rankFailures(rows as never);
    assert.equal(r.failed, 3);
    assert.deepEqual(r.table.map((x) => [x.cls, x.builds]), [["compile", 2], ["timeout_limit", 1]]);
  });
});

describe("journal stats keep the old numbers beside the real pass", () => {
  it("an old journal (no real block): old pass@1/final unchanged, real section + taxonomy printed", () => {
    const rows: StatRow[] = [
      { job: "a", lane: "plain", pass: true, firstAttempt: true, repairs: 0, costUsd: 0.1, result: { status: "succeeded", pass: true, repairs: 0, stages: stages() as never, flight: flight({ boot: "pass", plugins_enabled: "pass" }) } },
      { job: "b", lane: "creature", pass: true, firstAttempt: true, repairs: 0, costUsd: 0.3, result: { status: "succeeded", pass: true, repairs: 0, stages: stages() as never, flight: flight({ boot: "pass", plugins_enabled: "fail" }, "failed") } },
      { job: "c", lane: "plain", pass: false, firstAttempt: false, repairs: 1, costUsd: 0.2, result: { status: "failed", errorCode: "compile", pass: false, repairs: 1, stages: stages({ compile: ["fail"] }) as never, flight: null } },
    ];
    const s = journalStats(rows);
    assert.equal(s.passAt1Pct, 66.7);
    assert.equal(s.finalPassPct, 66.7);
    assert.equal(s.real?.realPassPct, 33.3);
    assert.equal(s.real?.stages.pluginEnabled.fail, 1);
    assert.equal(s.failures.failed, 2);
    const text = statsText(s);
    assert.match(text, /REAL PASS 33.3%/);
    assert.match(text, /failure taxonomy/);
    assert.match(text, /plugin did not enable/);
  });
  it("rows without a result (legacy callers) still work", () => {
    const s = journalStats([{ job: "a", lane: "plain", pass: true, firstAttempt: true, repairs: 0, costUsd: 0.1 }]);
    assert.equal(s.real, null);
    assert.equal(s.finalPassPct, 100);
  });
  it("launch-check summary reports real pass and booted-but-not-enabled", () => {
    const ok = { job: "a", lane: "plain", pass: true, firstAttempt: true, status: "succeeded", stages: stages(), flight: flight({ boot: "pass", plugins_enabled: "pass" }), repairs: 0 };
    const gob = { job: "b", lane: "creature", pass: true, firstAttempt: true, status: "succeeded", stages: stages(), flight: flight({ boot: "pass", plugins_enabled: "fail" }, "failed"), repairs: 0 };
    const s = summarizeResults([ok, gob]);
    assert.equal(s.finalPassPct, 100);
    assert.equal(s.realPassPct, 50);
    assert.equal(s.bootedNotEnabled, 1);
  });
});

describe("gate backward compatibility", () => {
  const row = (job: string, o: Partial<GateRow> = {}): GateRow => ({ job, lane: "plain", pass: true, firstAttempt: true, full: true, costUsd: 0.1, repairs: 0, ...o });
  it("references without real pass compare exactly as before (no real fields)", () => {
    const c = compareRuns([row("a", { realPass: false, realFirst: false })], [row("a")], "baseline", "old");
    assert.equal(c.realRegressions, undefined);
    assert.equal(c.delta.realPass, undefined);
  });
  it("a job that was a real pass and is not now is a real regression; verdict reacts", () => {
    const ref = ["a", "b", "c"].map((j) => row(j, { realPass: true, realFirst: true }));
    const now = ["a", "b", "c"].map((j) => row(j, { realPass: j === "c", realFirst: false }));
    const v = gateVerdict({ tag: "t", mode: "recorded", rows: now, refs: [{ against: "baseline", name: "b", rows: ref }], planned: ["a", "b", "c"] });
    assert.equal(v.verdict, "fail");
    assert.match(v.reasons.join(" "), /real pass/);
    assert.equal(metricsOf(now).realPassPct, 33.3);
    assert.equal(metricsOf([row("x")]).realPassPct, undefined);
  });
  it("rows from references and journals carry realPass when present", () => {
    assert.equal(rowsFromReference({ results: [{ job: "a", lane: "plain", pass: true, realPass: false }] })[0].realPass, false);
    const j = JSON.stringify({ t: "done", job: "a", result: { lane: "plain", status: "succeeded", pass: true, repairs: 0, stages: stages(), flight: flight({ boot: "pass", plugins_enabled: "fail" }, "failed") } });
    assert.equal(rowsFromJournal(j)[0].realPass, false);
  });
});

describe("real-world corpus v1", () => {
  const rw = loadRealWorld();
  it("60-100 unique prompts, in the stated proportions, every one tagged", () => {
    assert.ok(rw.length >= 60 && rw.length <= 100);
    assert.equal(new Set(rw.map((p) => p.key)).size, rw.length);
    const share = (s: string) => rw.filter((p) => p.stratum === s).length / rw.length;
    assert.ok(Math.abs(share("creature") - 0.3) <= 0.03);
    assert.ok(Math.abs(share("gui_economy_quests") - 0.25) <= 0.03);
    assert.ok(Math.abs(share("items") - 0.2) <= 0.03);
    assert.ok(Math.abs(share("datapack_world") - 0.1) <= 0.03);
    assert.ok(Math.abs(share("admin_minigames") - 0.15) <= 0.03);
    for (const p of rw) { assert.ok(p.mustHave?.kind && p.mustHave.value, p.key); assert.ok(p.style, p.key); assert.ok(p.prompt.length > 8, p.key); assert.equal(p.must_refuse, false); }
    for (const s of ["short_vague", "run_on", "typos", "wrong_genre"]) assert.ok(rw.some((p) => p.style === s), s);
    const existing = new Set(loadEvalSet().map((p) => p.key));
    for (const p of rw) assert.ok(!existing.has(p.key), `${p.key} collides with the legacy set`);
  });
  it("the smoke subset is 24 prompts and spans every stratum", () => {
    const sm = rw.filter((p) => p.smoke);
    assert.equal(sm.length, 24);
    assert.deepEqual([...new Set(sm.map((p) => p.stratum))].sort(), ["admin_minigames", "creature", "datapack_world", "gui_economy_quests", "items"]);
  });
  it("creature prompts request the creature lane (the goblin shape) and plan with a cost estimate", () => {
    const g = rw.find((p) => p.key === "rw-goblin-steal")!;
    assert.equal(laneOf(g), "creature");
    assert.equal((assetsRequest(g) as { creature?: boolean }).creature, true);
    const plan = planRun([...loadEvalSet(), ...rw], loadMatrix(), { versions: ["1.21.11"], keys: rw.map((p) => p.key) }, { tag: "rw-test" });
    assert.equal(plan.jobs.length, rw.length);
    assert.ok(plan.estimate.high > plan.estimate.low && plan.estimate.low > 0);
    assert.ok(plan.jobs.some((j) => j.lane === "creature"));
  });
  it("owner journal fixture: every corpus lane resolves to a known lane", () => {
    for (const p of rw) assert.ok(["texture", "sound", "designer", "datapack", "plain", "creature"].includes(laneOf(p)), `${p.key} -> ${laneOf(p)}`);
  });
});

describe("eval-run presets (dry run, no spend)", () => {
  it("--preset real-world and real-world-smoke print a plan and a stratum estimate", async () => {
    const { spawnSync } = await import("node:child_process");
    const ROOT = path.join(__dirname, "..");
    for (const [preset, n] of [["real-world", 80], ["real-world-smoke", 24]] as const) {
      const r = spawnSync(process.execPath, [path.join(ROOT, "node_modules/.bin/tsx"), path.join(ROOT, "scripts/cyrus/eval-run.ts"), "--dry-run", "--preset", preset], { encoding: "utf8", cwd: ROOT });
      assert.equal(r.status, 0, r.stderr);
      assert.match(r.stdout, new RegExp(`${n} builds`));
      assert.match(r.stdout, /by stratum/);
      assert.match(r.stdout, /estimated cost/);
    }
  });
  it("the eval-journal-stats CLI prints stages and taxonomy on a recorded journal", async () => {
    const { spawnSync } = await import("node:child_process");
    const ROOT = path.join(__dirname, "..");
    const j = path.join(ROOT, "test/fixtures/cyrus-eval-gate/journal.jsonl");
    assert.ok(fs.existsSync(j));
    const r = spawnSync(process.execPath, [path.join(ROOT, "node_modules/.bin/tsx"), path.join(ROOT, "scripts/cyrus/eval-journal-stats.ts"), j], { encoding: "utf8", cwd: ROOT });
    assert.equal(r.status, 0, r.stderr);
    assert.match(r.stdout, /REAL PASS/);
    assert.match(r.stdout, /plugin enabled/);
    assert.match(r.stdout, /pass@1/);
  });
});
